const fs = require('fs');
const path = require('path');
const http = require('http');

const URL = 'http://127.0.0.1:53735/status';
const OUT_DIR = path.join(__dirname, 'results');
const OUT_FILE = path.join(OUT_DIR, 'status.json');

function fetchStatus(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        try {
          resolve({ httpCode: res.statusCode, body: JSON.parse(data) });
        } catch (err) {
          reject(err);
        }
      });
    }).on('error', reject);
  });
}

(async () => {
  try {
    const { httpCode, body } = await fetchStatus(URL);
    fs.mkdirSync(OUT_DIR, { recursive: true });
    fs.writeFileSync(OUT_FILE, JSON.stringify(body, null, 2));
    console.log(`Wrote ${OUT_FILE} (http=${httpCode})`);
  } catch (err) {
    console.error('Error:', err.message);
    process.exit(1);
  }
})();

